"""Generate an ArcPy script that imports the point table into ArcGIS Pro.

The script is GENERATED, not executed here: ArcPy is not available outside ArcGIS Pro, so
it is untested until you run it in ArcGIS Pro. IDW is left switched off (RUN_IDW = False).
"""
from __future__ import annotations

from pathlib import Path

from .. import __version__, config

_TEMPLATE = '''# -*- coding: utf-8 -*-
"""Generated by {app} v{version}.
Run inside ArcGIS Pro (Python window or notebook).
NOTE: generated automatically and NOT tested by the generator - check the paths and outputs.
Input table CRS: WGS 84 (EPSG:4326). Flags: idw_valid = 1 means finite rainfall, no QC error,
not a duplicate location (see points_fields.csv).
"""
import arcpy

CSV_PATH = {csv!r}
OUT_NAME = {out_name!r}
VALUE_FIELD = {value_field!r}

arcpy.env.overwriteOutput = True
aprx = arcpy.mp.ArcGISProject("CURRENT")
OUT_FC = aprx.defaultGeodatabase + "\\\\" + OUT_NAME

# 1) CSV -> point feature class (x = longitude, y = latitude, WGS 84)
arcpy.management.XYTableToPoint(CSV_PATH, OUT_FC, "longitude", "latitude", None,
                                arcpy.SpatialReference(4326))
print("Created", OUT_FC, "with", arcpy.management.GetCount(OUT_FC)[0], "points")

# 2) layer with only the usable points (no duplicates / QC errors / missing rainfall)
arcpy.management.MakeFeatureLayer(OUT_FC, OUT_NAME + "_valid", "idw_valid = 1")
print("Usable points:", arcpy.management.GetCount(OUT_NAME + "_valid")[0])

# 3) OPTIONAL: IDW with Spatial Analyst (off by default)
RUN_IDW = False
CELL_SIZE = 0.05      # degrees, because the points are in EPSG:4326 (project first for metres)
POWER = 2
NEIGHBORS = 12
if RUN_IDW:
    arcpy.CheckOutExtension("Spatial")
    out_raster = arcpy.sa.Idw(OUT_NAME + "_valid", VALUE_FIELD, CELL_SIZE, POWER,
                              arcpy.sa.RadiusVariable(NEIGHBORS))
    out_raster.save(aprx.defaultGeodatabase + "\\\\" + OUT_NAME + "_idw")
    arcpy.CheckInExtension("Spatial")
'''


def write_arcpy_script(path, csv_path, out_name: str = "points_rainfall",
                       value_field: str = "mean_annual_rain_mm") -> Path:
    text = _TEMPLATE.format(app=config.APP_NAME, version=__version__, csv=str(csv_path),
                            out_name=out_name, value_field=value_field)
    path = Path(path)
    path.write_text(text, encoding="utf-8")
    return path
